class GSLMatrix(ctypes.Structure):
    _fields_ = [('size1', ctypes.c_size_t),
                ('size2', ctypes.c_size_t),
                ('tda', ctypes.c_size_t),
                ('data', ctypes.POINTER(ctypes.c_double)),
                ('block', ctypes.c_void_p),
                ('owner', ctypes.c_int)]

def create_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray) or np_array.dtype != np.float64:
        raise ValueError('Input must be a numpy array of type float64')
    rows, cols = np_array.shape
    data_ptr = np_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
    return GSLMatrix(size1=rows, size2=cols, tda=cols, data=data_ptr, block=None, owner=0)

