import ctypes
import sys

def load_gsl_libraries():
    try:
        ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
        return gsl
    except OSError as e:
        sys.stderr.write(f'Error loading GSL libraries: {e}\n')
        sys.exit(1)

def set_ieee_mode(gsl, precision, rounding, exception_mask):
    gsl.gsl_ieee_set_mode.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_int]
    gsl.gsl_ieee_set_mode.restype = ctypes.c_int
    result = gsl.gsl_ieee_set_mode(precision, rounding, exception_mask)
    return result

def main():
    if len(sys.argv) != 4:
        sys.stderr.write('Usage: python program.py <precision> <rounding> <exception_mask>\n')
        sys.exit(1)
    try:
        precision = int(sys.argv[1])
        rounding = int(sys.argv[2])
        exception_mask = int(sys.argv[3])
    except ValueError:
        sys.stderr.write('All inputs must be integers.\n')
        sys.exit(1)
    gsl = load_gsl_libraries()
    result = set_ieee_mode(gsl, precision, rounding, exception_mask)
