import ctypes

class GSLException(Exception):
    pass

class GSL:
    def __init__(self):
        self._load_libraries()
        self._define_types()
        self._define_functions()

    def _load_libraries(self):
        ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

    def _define_types(self):
        self.gsl_interp_type = ctypes.c_void_p
        self.gsl_spline = ctypes.c_void_p

    def _define_functions(self):
        self.gsl.gsl_spline_alloc.argtypes = [ctypes.POINTER(self.gsl_interp_type), ctypes.c_size_t]
        self.gsl.gsl_spline_alloc.restype = ctypes.POINTER(self.gsl_spline)

    def allocate_spline(self, interp_type_name, size):
        interp_type = self._get_interp_type(interp_type_name)
        if not interp_type:
            raise GSLException(f'Invalid interpolation type: {interp_type_name}')
        if size <= 0:
            raise GSLException('Size must be a positive integer')
        spline_ptr = self.gsl.gsl_spline_alloc(interp_type, size)
        if not spline_ptr:
            raise GSLException('Failed to allocate spline')
        return spline_ptr

    def _get_interp_type(self, interp_type_name):
        interp_types = {
            'linear': self.gsl.gsl_interp_linear,
            'polynomial': self.gsl.gsl_interp_polynomial,
            'cspline': self.gsl.gsl_interp_cspline,
            'cspline_periodic': self.gsl.gsl_interp_cspline_periodic,
            'akima': self.gsl.gsl_interp_akima,
            'akima_periodic': self.gsl.gsl_interp_akima_periodic
        }
        return interp_types.get(interp_type_name)

