class GSLException(Exception):
    pass

def numpy_to_gsl_matrix_complex(np_array):
    rows, cols = np_array.shape
    gsl_matrix_complex = gsl.gsl_matrix_complex_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_complex_set(gsl_matrix_complex, i, j, np_array[i, j])
    return gsl_matrix_complex

def gsl_vector_to_numpy(gsl_vector, size):
    np_array = np.zeros(size, dtype=np.complex128)
    for i in range(size):
        np_array[i] = gsl.gsl_vector_complex_get(gsl_vector, i)
    return np_array

def compute_eigenvalues(A, B):
    if not (isinstance(A, np.ndarray) and isinstance(B, np.ndarray)):
        raise ValueError("Input matrices must be NumPy arrays.")
    if A.shape != B.shape:
        raise ValueError("Matrices A and B must have the same shape.")

    rows, cols = A.shape
    if rows != cols:
        raise ValueError("Matrices must be square.")

    gsl_A = numpy_to_gsl_matrix_complex(A)
    gsl_B = numpy_to_gsl_matrix_complex(B)

    gsl_eigenvalues = gsl.gsl_vector_complex_alloc(rows)
    gsl_workspace = gsl.gsl_eigen_genherm_alloc(rows)

    status = gsl.gsl_eigen_genherm(gsl_A, gsl_B, gsl_eigenvalues, gsl_workspace)
    if status != 0:
        raise GSLException("Error computing eigenvalues.")

    eigenvalues = gsl_vector_to_numpy(gsl_eigenvalues, rows)

    gsl.gsl_matrix_complex_free(gsl_A)
    gsl.gsl_matrix_complex_free(gsl_B)
    gsl.gsl_vector_complex_free(gsl_eigenvalues)
    gsl.gsl_eigen_genherm_free(gsl_workspace)

