import ctypes
import numpy as np

class gsl_function(ctypes.Structure):
    _fields_ = [("function", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)),
                ("params", ctypes.c_void_p)]

def my_function(x):
    return np.sin(x)

FUNC_TYPE = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)
def c_function(x, params):
    return my_function(x)

ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def create_workspace(limit):
    gsl.gsl_integration_workspace_alloc.restype = ctypes.POINTER(ctypes.c_void_p)
    return gsl.gsl_integration_workspace_alloc(limit)

def free_workspace(workspace):
    gsl.gsl_integration_workspace_free(workspace)

def create_qaws_table():
    gsl.gsl_integration_qaws_table_alloc.restype = ctypes.POINTER(ctypes.c_void_p)
    return gsl.gsl_integration_qaws_table_alloc(0, 0, 0, 0)

def free_qaws_table(table):
    gsl.gsl_integration_qaws_table_free(table)

def gsl_integration_qaws(f, a, b, table, epsabs, epsrel, limit, workspace):
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    gsl.gsl_integration_qaws(f, a, b, table, epsabs, epsrel, limit, workspace, ctypes.byref(result), ctypes.byref(abserr))
    return result.value, abserr.value

def main():
    a = 0.0
    b = np.pi
    epsabs = 1e-7
    epsrel = 1e-7
    limit = 1000

    workspace = create_workspace(limit)
    table = create_qaws_table()

    f = gsl_function(FUNC_TYPE(c_function), None)

    result, abserr = gsl_integration_qaws(f, a, b, table, epsabs, epsrel, limit, workspace)

    free_workspace(workspace)
    free_qaws_table(table)

    assert np.isclose(result, 2.0, atol=epsabs, rtol=epsrel), "Integration result is incorrect."

    return result, abserr

if __name__ == "__main__":
    result, abserr = main()
    print(f"Result: {result}, Estimated Absolute Error: {abserr}")

