class GSLHistogram:
    def __init__(self, n_bins):
        self.n_bins = n_bins
        self.histogram = gsl.gsl_histogram_alloc(n_bins)
        if not self.histogram:
            raise MemoryError('Failed to allocate memory for histogram')

    def __del__(self):
        if self.histogram:
            gsl.gsl_histogram_free(self.histogram)

    def reset(self):
        gsl.gsl_histogram_reset(self.histogram)

    def set_bins(self, values):
        if len(values) != self.n_bins:
            raise ValueError('Number of values must match number of bins')
        for i, value in enumerate(values):
            gsl.gsl_histogram_set(self.histogram, i, value)

    def get_bins(self):
        bins = np.zeros(self.n_bins)
        for i in range(self.n_bins):
            bins[i] = gsl.gsl_histogram_get(self.histogram, i)
        return bins

