        self.gsl.gsl_rng_type_lookup.argtypes = [ctypes.c_char_p]

        self.gsl.gsl_rng_free.restype = None
        self.gsl.gsl_rng_free.argtypes = [ctypes.POINTER(ctypes.c_void_p)]

