        self.gsl.gsl_qrng_halton.restype = ctypes.c_void_p
        self.gsl.gsl_qrng_free.argtypes = [ctypes.c_void_p]
        self.gsl.gsl_qrng_get.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_double)]
        self.generator = self.gsl.gsl_qrng_halton(self.dimension)

    def generate_halton_point(self):
        point = (ctypes.c_double * self.dimension)()
        self.gsl.gsl_qrng_get(self.generator, point)
        return list(point)

    def __del__(self):
        if hasattr(self, 'generator'):
            self.gsl.gsl_qrng_free(self.generator)


