class GSLNormCalculator:
    def __init__(self):
        try:
            ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        except OSError as e:
            raise RuntimeError("Failed to load GSL libraries. Ensure they are installed and the paths are correct.") from e

        self.cblas_dnrm2 = self.gsl.cblas_dnrm2
        self.cblas_dnrm2.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int]
        self.cblas_dnrm2.restype = ctypes.c_double

    def compute_euclidean_norm(self, vector):
        if not isinstance(vector, list) or not all(isinstance(x, (float, int)) for x in vector):
            raise ValueError("Input must be a list of numbers.")

        n = len(vector)
        if n == 0:
            return 0.0

        array_type = ctypes.c_double * n
        c_vector = array_type(*vector)
        stride = 1

        norm = self.cblas_dnrm2(n, c_vector, stride)
        return float(norm)

