class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = (ctypes.c_double * (rows * cols))()

    def __getitem__(self, index):
        row, col = index
        return self.data[row * self.cols + col]

    def __setitem__(self, index, value):
        row, col = index
        self.data[row * self.cols + col] = value

    def to_numpy(self):
        return np.array(self.data).reshape(self.rows, self.cols)

def matrix_to_gsl(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    gsl_matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl_matrix[i, j] = matrix[i][j]
    return gsl_matrix

