import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.validate_square_matrix()

    def validate_square_matrix(self):
        if not all(len(row) == self.size for row in self.data):
            raise ValueError("Input must be a square matrix.")

    def to_gsl_matrix(self):
        flat_data = np.array(self.data, dtype=np.float64).flatten()
        return flat_data.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    def from_gsl_matrix(self, gsl_matrix_ptr):
        result = np.ctypeslib.as_array(gsl_matrix_ptr, shape=(self.size, self.size))
        return result.tolist()

def matrix_to_gsl(matrix):
    return GSLMatrix(matrix)

def gsl_matrix_to_numpy(gsl_matrix):
    return gsl_matrix.from_gsl_matrix()

def compute_matrix_exponential(matrix, mode):
    # Load the GSL libraries
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define the function prototype for gsl_linalg_exponential_ss
    gsl.gsl_linalg_exponential_ss.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_linalg_exponential_ss.restype = ctypes.c_int

    # Convert the input matrix to GSL format
    gsl_matrix = matrix_to_gsl(matrix)
    input_gsl_matrix = gsl_matrix.to_gsl_matrix()

    # Prepare the output matrix
    output_gsl_matrix = (ctypes.c_double * (gsl_matrix.size * gsl_matrix.size))()

    # Call the GSL function
    status = gsl.gsl_linalg_exponential_ss(input_gsl_matrix, gsl_matrix.size, output_gsl_matrix)
