class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.gsl_matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        gsl.gsl_matrix_free(self.gsl_matrix)

def matrix_to_gsl(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    gsl_matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set(gsl_matrix.gsl_matrix, i, j, matrix[i][j])
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix, rows, cols):
    result = np.zeros((rows, cols))
    for i in range(rows):
        for j in range(cols):
            result[i][j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
    return result.tolist()

def compute_matrix_exponential(matrix, mode):
    if not matrix or not all(len(row) == len(matrix) for row in matrix):
        raise ValueError("Input must be a square matrix.")

    rows = len(matrix)
    cols = len(matrix[0])

    gsl_matrix = matrix_to_gsl(matrix)
    result_matrix = GSLMatrix(rows, cols)

    status = gsl.gsl_linalg_exponential_ss(gsl_matrix.gsl_matrix, result_matrix.gsl_matrix, mode)
    if status != 0:
        raise RuntimeError("Error computing matrix exponential.")

    return gsl_matrix_to_numpy(result_matrix.gsl_matrix, rows, cols)

