import ctypes

class RingBuf(ctypes.Structure):
    pass

def initialize_ringbuf(size):
    ringbuf_init = gsl.gsl_ringbuf_alloc
    ringbuf_init.argtypes = [ctypes.c_size_t]
    ringbuf_init.restype = ctypes.POINTER(RingBuf)
    ringbuf = ringbuf_init(size)
    if not ringbuf:
        raise MemoryError("Failed to allocate ring buffer.")
    return ringbuf

def insert_into_ringbuf(ringbuf, values):
    ringbuf_insert = gsl.gsl_ringbuf_insert
    ringbuf_insert.argtypes = [ctypes.POINTER(RingBuf), ctypes.c_int]
    for value in values:
        result = ringbuf_insert(ringbuf, value)
        if result != 0:
            raise RuntimeError(f"Failed to insert value {value} into ring buffer.")

def copy_ringbuf_to_list(ringbuf):
    ringbuf_copy = gsl.gsl_ringbuf_to_list
    ringbuf_copy.argtypes = [ctypes.POINTER(RingBuf), ctypes.POINTER(ctypes.c_int)]
    ringbuf_copy.restype = ctypes.c_size_t

    size = gsl.gsl_ringbuf_size(ringbuf)
    buffer = (ctypes.c_int * size)()
    copied_size = ringbuf_copy(ringbuf, buffer)
    if copied_size != size:
        raise RuntimeError("Failed to copy ring buffer to list.")
    return list(buffer)

