from ctypes import c_double, c_size_t, POINTER

class GSLHistogram:
    def __init__(self, bins):
        self.libcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        self.histogram = self.gsl.gsl_histogram_alloc(bins)
        self.gsl.gsl_histogram_set_ranges_uniform.argtypes = [ctypes.c_void_p, c_double, c_double]
        self.gsl.gsl_histogram_increment.argtypes = [ctypes.c_void_p, c_double]
        self.gsl.gsl_histogram_get.argtypes = [ctypes.c_void_p, c_size_t]
        self.gsl.gsl_histogram_get.restype = c_double
        self.gsl.gsl_histogram_range.argtypes = [ctypes.c_void_p, c_size_t, POINTER(c_double), POINTER(c_double)]
        self.gsl.gsl_histogram_range.restype = None

    def set_ranges_uniform(self, xmin, xmax):
        self.gsl.gsl_histogram_set_ranges_uniform(self.histogram, xmin, xmax)

    def increment(self, value):
        self.gsl.gsl_histogram_increment(self.histogram, value)

    def get_bin_count(self, bin_index):
        return self.gsl.gsl_histogram_get(self.histogram, bin_index)

    def get_bin_range(self, bin_index):
        lower = c_double()
        upper = c_double()
        self.gsl.gsl_histogram_range(self.histogram, bin_index, ctypes.byref(lower), ctypes.byref(upper))
        return (lower.value, upper.value)

    def free(self):
        self.gsl.gsl_histogram_free(self.histogram)


def compute_histogram(data, xmin, xmax):
    bins = int(xmax - xmin)
    histogram = GSLHistogram(bins)
    histogram.set_ranges_uniform(xmin, xmax)
    for value in data:
        histogram.increment(value)
    result = []
    for i in range(bins):
        lower_bound, upper_bound = histogram.get_bin_range(i)
        count = histogram.get_bin_count(i)
        result.append((lower_bound, upper_bound, count))
    histogram.free()
    return result

